[
  {
    "statement": "The success of providing artificial nest sites differs significantly between solitary bees and bumblebees.",
    "citations": []
  },
  {
    "statement": "Solitary bees show much higher success rates in occupying artificial nest sites than bumblebees do.",
    "citations": []
  },
  {
    "statement": "For solitary bees, 29 out of 30 replicated trials showed occupancy by bees across 10 countries, including Europe, North and South America, and Asia.",
    "citations": [
      "Action 47"
    ]
  },
  {
    "statement": "Reported occupancy rates for solitary bee nest boxes were between 1% and 26% of available cavities.",
    "citations": [
      "Action 80"
    ]
  },
  {
    "statement": "The number of occupied solitary bee nests can double over three years with repeated nest box provision at a given site.",
    "citations": [
      "Action 47"
    ]
  },
  {
    "statement": "The doubling of occupied solitary bee nests was demonstrated in three trials on agricultural land.",
    "citations": [
      "Action 47"
    ]
  },
  {
    "statement": "One study estimated that the number of foraging Osmia bees had increased in fields with nest boxes compared to fields without nest boxes.",
    "citations": [
      "Action 47"
    ]
  },
  {
    "statement": "In contrast to solitary bees, bumblebee nest box success is much lower.",
    "citations": []
  },
  {
    "statement": "Three replicated trials since 1989 in the UK showed very low uptake rates of 0-2.5% for various bumblebee nest box designs.",
    "citations": [
      "Action 48"
    ]
  },
  {
    "statement": "Seven earlier trials in the UK, USA, or Canada showed overall bumblebee nest box uptake rates between 10% and 48%.",
    "citations": [
      "Action 48"
    ]
  },
  {
    "statement": "Two replicated trials that tested bumblebee nest boxes both found very low uptake of 2% or less.",
    "citations": [
      "Action 80"
    ]
  },
  {
    "statement": "Underground nest boxes buried 5-10 cm underground with entrance pipes are generally the most effective for bumblebees.",
    "citations": [
      "Action 48"
    ]
  },
  {
    "statement": "Seven replicated trials of underground bumblebee nest boxes found between 6% and 58% occupancy.",
    "citations": [
      "Action 48"
    ]
  },
  {
    "statement": "The occupancy rates for even the most effective bumblebee nest boxes are often lower than solitary bee success rates.",
    "citations": [
      "Action 48"
    ]
  },
  {
    "statement": "There is no evidence captured for the effects of providing nest boxes on bumblebee populations.",
    "citations": [
      "Action 48"
    ]
  }
]

[
  {
    "statement": "Several actions related to reducing farming intensity can benefit wild bees.",
    "citations": []
  },
  {
    "statement": "Two replicated trials in Europe found enhanced numbers and diversity of wild bees on farmland meadows with a delayed first cut and little agrochemical use compared to conventionally farmed meadows.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "Reducing grazing intensity on pastures can increase the abundance of cavity-nesting bees and wasps.",
    "citations": [
      "23"
    ]
  },
  {
    "statement": "One replicated trial demonstrated that reducing summer cattle grazing intensity increased bee abundance.",
    "citations": [
      "23"
    ]
  },
  {
    "statement": "Evidence on the effect of reduced tillage on bees shows mixed results.",
    "citations": [
      "11"
    ]
  },
  {
    "statement": "One replicated trial on squash farms in the USA showed no difference in bee abundance between tilled and untilled farms.",
    "citations": [
      "11"
    ]
  },
  {
    "statement": "Another replicated trial on squash farms in the USA found three times more squash bees on no-till farms than on conventional farms.",
    "citations": [
      "11"
    ]
  },
  {
    "statement": "Converting to organic farming shows equivocal evidence for benefitting wild bees.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "Three replicated trials in Europe or Canada demonstrated higher wild bee abundance under organic arable farming than under conventional farming.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "One trial showed higher bee diversity in organically farmed wheat fields.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "Three other replicated trials in Europe or the USA found no significant difference in bumblebee numbers, bumblebee species, or wild bees visiting flowering crops between conventional and organic farms.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "One replicated trial in the USA showed that numbers of foraging bees on squash farms are not affected by the responsible use of pesticides.",
    "citations": [
      "27"
    ]
  },
  {
    "statement": "Agri-environment schemes have shown variable results for wild bees.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Four replicated trials in Europe demonstrated enhanced diversity and/or abundance of foraging wild bees under various European agri-environment schemes compared to conventionally-managed fields.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Four other replicated trials found no enhancement in bee numbers or species under agri-environment schemes.",
    "citations": [
      "24"
    ]
  }
]
